using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(" ", args) : "the impact of large language models on software development";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the chat client with tool support
var openAiClient = new OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-key-here");
IChatClient chatClient = openAiClient.GetChatClient("gpt-4o").AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Define the tools
var notepad = new ResearchNotepad();
var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information on a given query and returns relevant results."),
    AIFunctionFactory.Create(
        ([Description("The note content to save")] string note, [Description("A short label for the note")] string label) =>
            notepad.AddNote(label, note),
        "save_note",
        "Saves a research note with a label for later reference."),
    AIFunctionFactory.Create(
        () => notepad.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes.")
};

var chatOptions = new ChatOptions { Tools = tools };

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Saving important findings as notes
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary

        Be systematic: search for different aspects of the topic, save key findings, then synthesize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

// Agent loop
const int maxIterations = 15;
for (int i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);
    messages.Add(new ChatMessage(ChatRole.Assistant, response.Message.Contents));

    // Check if the model is done (no more tool calls)
    if (response.Message.Contents.OfType<FunctionCallContent>().Any() == false)
    {
        Console.WriteLine("\n=== Research Summary ===\n");
        Console.WriteLine(response.Message.Text);
        break;
    }
}

Console.WriteLine("\n=== Research Notes Collected ===");
foreach (var (label, note) in notepad.Notes)
{
    Console.WriteLine($"\n[{label}]: {note}");
}

// --- Tool implementations ---

public static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  [🔍 Searching]: {query}");

        // Use a public search API (DuckDuckGo instant answer)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await Http.GetStringAsync(url);

            var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            if (root.TryGetProperty("AbstractText", out var abstractText) && abstractText.GetString() is { Length: > 0 } abs)
                results.Add($"Summary: {abs}");

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        results.Add($"- {t}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"Search for '{query}' returned limited results. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

public class ResearchNotepad
{
    public List<(string Label, string Content)> Notes { get; } = [];

    public string AddNote(string label, string note)
    {
        Notes.Add((label, note));
        Console.WriteLine($"  [📝 Note saved]: {label}");
        return $"Note '{label}' saved successfully. Total notes: {Notes.Count}";
    }

    public string GetAllNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", Notes.Select((n, i) => $"[{i + 1}] {n.Label}:\n{n.Content}"));
    }
}

