         "save_note",
         "Saves a research note with a label for later reference."),
     AIFunctionFactory.Create(
         () => notepad.GetAllNotes(),
         "get_notes",
         "Retrieves all saved research notes.")
 };

 var chatOptions = new ChatOptions { Tools = tools };

 var messages = new List<ChatMessage>
 {
     new(ChatRole.System, """
         You are a research agent. Your goal is to research a topic thoroughly by:
         1. Searching the web for relevant information (make multiple searches with different queries)
         2. Saving important findings as notes
         3. After gathering enough information, retrieve your notes and provide a comprehensive summary

         Be systematic: search for different aspects of the topic, save key findings, then synthesize.
         """),
     new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
 };

 // Run the agent - FunctionInvocation middleware handles the tool call loop automatically
 var response = await chatClient.GetResponseAsync(messages, chatOptions);

 Console.WriteLine("\n=== Research Summary ===\n");
