 public static class WebSearchTool
 {
     private static readonly HttpClient Http = new();

     public static async Task<string> SearchAsync(string query)
     {
         Console.WriteLine($"  [🔍 Searching]: {query}");

         // Use a public search API (DuckDuckGo instant answer)
         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var response = await Http.GetStringAsync(url);

             var doc = System.Text.Json.JsonDocument.Parse(response);
             var root = doc.RootElement;

             var results = new List<string>();

             if (root.TryGetProperty("AbstractText", out var abstractText) && abstractText.GetString() is { Length: > 0 } abs)
                 results.Add($"Summary: {abs}");

             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var item in topics.EnumerateArray().Take(5))
                 {
                     if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                         results.Add($"- {t}");
                 }
             }

             return results.Count > 0
                 ? string.Join("\n", results)
                 : $"Search for '{query}' returned limited results. Try a more specific query.";
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }
 }

 public class ResearchNotepad
 {
     public List<(string Label, string Content)> Notes { get; } = [];

     public string AddNote(string label, string note)
     {
         Notes.Add((label, note));
         Console.WriteLine($"  [📝 Note saved]: {label}");
         return $"Note '{label}' saved successfully. Total notes: {Notes.Count}";
     }

     public string GetAllNotes()
     {
         if (Notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n\n", Notes.Select((n, i) => $"[{i + 1}] {n.Label}:\n{n.Content}"));
     }
 }
